<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Insecure = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # Skip TLS certificate validation</span></span>
